"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

type JobStatus = "queued" | "processing" | "completed" | "failed";

type JobResponse =
  | { ok: true; jobId: string }
  | { ok: false; error: string };

type StatusResponse =
  | {
      ok: true;
      job: {
        id: string;
        status: JobStatus;
        createdAt: string;
        updatedAt: string;
        inputType: "upload" | "youtube";
        originalName?: string;
        youtubeUrl?: string;
        durationSeconds?: number;
        segmentSeconds: number;
        segmentCount?: number;
        zipBytes?: number;
        error?: string;
      };
    }
  | { ok: false; error: string };

export default function Page() {
  const [mode, setMode] = useState<"upload" | "youtube">("upload");
  const [youtubeUrl, setYoutubeUrl] = useState("");
  const [jobId, setJobId] = useState<string | null>(null);
  const [status, setStatus] = useState<JobStatus | null>(null);
  const [statusDetails, setStatusDetails] = useState<StatusResponse["job"] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const fileRef = useRef<HTMLInputElement | null>(null);

  const downloadUrl = useMemo(() => {
    if (!jobId) return null;
    return `/api/jobs/${encodeURIComponent(jobId)}/download`;
  }, [jobId]);

  const fetchStatus = useCallback(async (id: string) => {
    const res = await fetch(`/api/jobs/${encodeURIComponent(id)}/status`, { method: "GET" });
    const data = (await res.json()) as StatusResponse;
    if (!data.ok) {
      setError(data.error);
      return;
    }
    setStatus(data.job.status);
    setStatusDetails(data.job);
    if (data.job.status === "failed" && data.job.error) setError(data.job.error);
  }, []);

  useEffect(() => {
    if (!jobId) return;
    let t: number | undefined;
    const tick = async () => {
      await fetchStatus(jobId);
    };
    tick().catch(() => {});
    t = window.setInterval(() => {
      tick().catch(() => {});
    }, 1500);
    return () => {
      if (t) window.clearInterval(t);
    };
  }, [jobId, fetchStatus]);

  const submitUpload = useCallback(async () => {
    setError(null);
    setBusy(true);
    setJobId(null);
    setStatus(null);
    setStatusDetails(null);

    try {
      const input = fileRef.current;
      const file = input?.files?.[0];
      if (!file) throw new Error("Nincs kiválasztott videófájl.");

      const fd = new FormData();
      fd.set("file", file, file.name);

      const res = await fetch("/api/jobs", { method: "POST", body: fd });
      const data = (await res.json()) as JobResponse;
      if (!data.ok) throw new Error(data.error);

      setJobId(data.jobId);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Ismeretlen hiba.");
    } finally {
      setBusy(false);
    }
  }, []);

  const submitYouTube = useCallback(async () => {
    setError(null);
    setBusy(true);
    setJobId(null);
    setStatus(null);
    setStatusDetails(null);

    try {
      const res = await fetch("/api/jobs", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ youtubeUrl })
      });
      const data = (await res.json()) as JobResponse;
      if (!data.ok) throw new Error(data.error);

      setJobId(data.jobId);
    } catch (e) {
      setError(e instanceof Error ? e.message : "Ismeretlen hiba.");
    } finally {
      setBusy(false);
    }
  }, [youtubeUrl]);

  return (
    <main>
      <h1 style={{ margin: "0 0 12px 0" }}>Videó feldarabolása 60 mp-es részekre</h1>

      <div style={{ display: "flex", gap: 12, alignItems: "center", marginBottom: 16, flexWrap: "wrap" }}>
        <label style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <input
            type="radio"
            name="mode"
            value="upload"
            checked={mode === "upload"}
            onChange={() => setMode("upload")}
            disabled={busy}
          />
          Fájl feltöltés
        </label>
        <label style={{ display: "flex", gap: 8, alignItems: "center" }}>
          <input
            type="radio"
            name="mode"
            value="youtube"
            checked={mode === "youtube"}
            onChange={() => setMode("youtube")}
            disabled={busy}
          />
          YouTube link
        </label>
      </div>

      {mode === "upload" ? (
        <section style={{ border: "1px solid #ddd", borderRadius: 10, padding: 16, marginBottom: 16 }}>
          <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
            <input ref={fileRef} type="file" accept="video/*" disabled={busy} />
            <button
              onClick={() => submitUpload()}
              disabled={busy}
              style={{ padding: "10px 14px", borderRadius: 8, border: "1px solid #333", background: "#111", color: "#fff" }}
            >
              Feldolgozás indítása
            </button>
          </div>
          <div style={{ marginTop: 10, color: "#444" }}>
            A darabolás mindig 0:00:00-tól indul, a szeletek hossza fixen 60 másodperc.
          </div>
        </section>
      ) : (
        <section style={{ border: "1px solid #ddd", borderRadius: 10, padding: 16, marginBottom: 16 }}>
          <div style={{ display: "flex", gap: 12, alignItems: "center", flexWrap: "wrap" }}>
            <input
              value={youtubeUrl}
              onChange={(e) => setYoutubeUrl(e.target.value)}
              placeholder=""
              disabled={busy}
              style={{ minWidth: 420, maxWidth: "100%", padding: 10, borderRadius: 8, border: "1px solid #aaa" }}
            />
            <button
              onClick={() => submitYouTube()}
              disabled={busy || youtubeUrl.trim().length === 0}
              style={{ padding: "10px 14px", borderRadius: 8, border: "1px solid #333", background: "#111", color: "#fff" }}
            >
              Feldolgozás indítása
            </button>
          </div>
          <div style={{ marginTop: 10, color: "#444" }}>
            A letöltést és konvertálást a szerver végzi, utána 60 mp-es MP4 részekből ZIP készül.
          </div>
        </section>
      )}

      {error ? (
        <div style={{ border: "1px solid #c00", color: "#900", borderRadius: 10, padding: 12, marginBottom: 16 }}>
          {error}
        </div>
      ) : null}

      {jobId ? (
        <section style={{ border: "1px solid #ddd", borderRadius: 10, padding: 16 }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
            <div>
              <strong>Job ID:</strong> {jobId}
            </div>
            <div>
              <strong>Állapot:</strong> {status ?? "..." }
            </div>
            {statusDetails?.durationSeconds != null ? (
              <div>
                <strong>Hossz:</strong> {Math.round(statusDetails.durationSeconds)} másodperc
              </div>
            ) : null}
            {statusDetails?.segmentCount != null ? (
              <div>
                <strong>Szeletek:</strong> {statusDetails.segmentCount} db
              </div>
            ) : null}
            {statusDetails?.zipBytes != null ? (
              <div>
                <strong>ZIP méret:</strong> {Math.round(statusDetails.zipBytes / 1024 / 1024 * 100) / 100} MB
              </div>
            ) : null}
            {status === "completed" && downloadUrl ? (
              <div style={{ marginTop: 6 }}>

                  ZIP letöltése

              </div>
            ) : null}
          </div>
        </section>
      ) : null}
    </main>
  );
}
