import { NextResponse } from "next/server";
import { z } from "zod";
import { createJobFromUpload, createJobFromYouTube, ensureJobSystemStarted } from "@/lib/jobs";
import { parseMultipartVideoUpload } from "@/lib/multipart";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const YouTubeSchema = z.object({ youtubeUrl: z.string().url().min(1) });

export async function POST(req: Request) {
  await ensureJobSystemStarted();

  const contentType = req.headers.get("content-type") || "";

  try {
    if (contentType.toLowerCase().startsWith("multipart/form-data")) {
      const job = await createJobFromUpload();
      const upload = await parseMultipartVideoUpload(req, job.paths.jobDir);
      await job.attachUploadedFile(upload.filePath, upload.originalFilename);
      await job.start();
      return NextResponse.json({ ok: true, jobId: job.record.id });
    }

    if (contentType.toLowerCase().includes("application/json")) {
      const body = await req.json();
      const parsed = YouTubeSchema.parse(body);
      const job = await createJobFromYouTube(parsed.youtubeUrl);
      await job.start();
      return NextResponse.json({ ok: true, jobId: job.record.id });
    }

    return NextResponse.json({ ok: false, error: "Nem támogatott Content-Type." }, { status: 415 });
  } catch (e) {
    const msg = e instanceof Error ? e.message : "Ismeretlen hiba.";
    return NextResponse.json({ ok: false, error: msg }, { status: 400 });
  }
}
