`app/api/jobs/[jobId]/download/route.ts`
```ts
import { NextResponse } from "next/server";
import { ensureJobSystemStarted, getJobPaths, getJobRecord } from "@/lib/jobs";
import { createReadStream } from "node:fs";
import { stat } from "node:fs/promises";
import { Readable } from "node:stream";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(_req: Request, ctx: { params: Promise<{ jobId: string }> }) {
  await ensureJobSystemStarted();
  const { jobId } = await ctx.params;

  const rec = await getJobRecord(jobId);
  if (!rec) return NextResponse.json({ ok: false, error: "Job nem található." }, { status: 404 });
  if (rec.status !== "completed") return NextResponse.json({ ok: false, error: "A ZIP még nem kész." }, { status: 409 });

  const paths = getJobPaths(jobId);
  const s = await stat(paths.zipPath);
  const nodeStream = createReadStream(paths.zipPath);

  const headers = new Headers();
  headers.set("content-type", "application/zip");
  headers.set("content-length", String(s.size));
  headers.set("content-disposition", `attachment; filename="segments_${jobId}.zip"`);
  headers.set("cache-control", "no-store");

  return new NextResponse(Readable.toWeb(nodeStream) as unknown as ReadableStream, { status: 200, headers });
}
