import { getEnv } from "@/lib/env";
import { execFile } from "@/lib/processors/exec";

export async function probeDurationSeconds(inputPath: string) {
  const env = getEnv();
  const args = ["-v", "error", "-show_entries", "format=duration", "-of", "default=noprint_wrappers=1:nokey=1", inputPath];
  const r = await execFile(env.FFPROBE_BIN, args);
  if (r.exitCode !== 0) throw new Error(r.stderr || "ffprobe hiba");
  const s = r.stdout.trim();
  const n = Number.parseFloat(s);
  if (!Number.isFinite(n) || n <= 0) throw new Error("Nem sikerült kiolvasni a videó hosszát.");
  return n;
}
