import { getEnv } from "@/lib/env";
import { execFile } from "@/lib/processors/exec";
import { ensureDir, listFiles } from "@/lib/fs";
import path from "node:path";

export async function splitIntoSegmentsMp4(opts: {
  inputPath: string;
  segmentsDir: string;
  segmentSeconds: number;
}) {
  const env = getEnv();
  await ensureDir(opts.segmentsDir);

  const outPattern = path.join(opts.segmentsDir, "part_%03d.mp4");
  const forceExpr = `expr:gte(t,n_forced*${opts.segmentSeconds})`;

  const args = [
    "-hide_banner",
    "-y",
    "-i",
    opts.inputPath,
    "-map",
    "0",
    "-c:v",
    "libx264",
    "-preset",
    "veryfast",
    "-crf",
    "18",
    "-pix_fmt",
    "yuv420p",
    "-force_key_frames",
    forceExpr,
    "-c:a",
    "aac",
    "-b:a",
    "192k",
    "-movflags",
    "+faststart",
    "-f",
    "segment",
    "-segment_time",
    String(opts.segmentSeconds),
    "-reset_timestamps",
    "1",
    outPattern
  ];

  const r = await execFile(env.FFMPEG_BIN, args);
  if (r.exitCode !== 0) throw new Error(r.stderr || "ffmpeg hiba");

  const files = (await listFiles(opts.segmentsDir))
    .filter((f) => f.toLowerCase().endsWith(".mp4"))
    .sort((a, b) => a.localeCompare(b, "en"));

  if (files.length === 0) throw new Error("Nem keletkeztek szeletek.");
  return { files };
}
