import { getEnv } from "@/lib/env";
import { execFile } from "@/lib/processors/exec";
import { listFiles, safeStat } from "@/lib/fs";
import path from "node:path";

export async function downloadYouTubeToMp4(opts: { youtubeUrl: string; jobDir: string }) {
  const env = getEnv();
  const outTemplate = path.join(opts.jobDir, "input.%(ext)s");

  const args = [
    "--no-playlist",
    "-f",
    "bestvideo[ext=mp4]+bestaudio[ext=m4a]/best[ext=mp4]/best",
    "--merge-output-format",
    "mp4",
    "-o",
    outTemplate,
    opts.youtubeUrl
  ];

  const r = await execFile(env.YTDLP_BIN, args);
  if (r.exitCode !== 0) throw new Error(r.stderr || "yt-dlp hiba");

  const preferred = path.join(opts.jobDir, "input.mp4");
  const st = await safeStat(preferred);
  if (st?.isFile()) return preferred;

  const files = await listFiles(opts.jobDir);
  const cand = files
    .filter((f) => path.basename(f).startsWith("input.") && !f.toLowerCase().endsWith(".part"))
    .sort((a, b) => a.localeCompare(b, "en"))[0];

  if (!cand) throw new Error("A YouTube letöltés nem hozott létre bemeneti fájlt.");
  return cand;
}
