import archiver from "archiver";
import { createWriteStream } from "node:fs";
import { stat } from "node:fs/promises";
import path from "node:path";
import { getEnv } from "@/lib/env";

export async function zipDirectoryFlat(opts: { sourceDir: string; zipPath: string }) {
  const env = getEnv();
  await new Promise<void>((resolve, reject) => {
    const output = createWriteStream(opts.zipPath);
    const archive = archiver("zip", { zlib: { level: env.ZIP_COMPRESSION_LEVEL } });

    output.on("close", () => resolve());
    output.on("error", (err) => reject(err));
    archive.on("error", (err) => reject(err));

    archive.pipe(output);
    archive.directory(opts.sourceDir, false);
    archive.finalize().catch(reject);
  });

  const s = await stat(opts.zipPath);
  return s.size;
}

export function zipPathForJob(jobDir: string) {
  return path.join(jobDir, "output.zip");
}
