`lib/multipart.ts`
```ts
import Busboy from "busboy";
import { createWriteStream } from "node:fs";
import path from "node:path";
import { ensureDir } from "@/lib/fs";
import { getEnv } from "@/lib/env";
import { Readable } from "node:stream";

export async function parseMultipartVideoUpload(req: Request, jobDir: string) {
  const env = getEnv();
  await ensureDir(jobDir);

  const headers: Record<string, string> = {};
  req.headers.forEach((v, k) => {
    headers[k.toLowerCase()] = v;
  });

  const contentType = headers["content-type"] || "";
  if (!contentType.toLowerCase().startsWith("multipart/form-data")) throw new Error("Hibás feltöltési kérés.");

  const body = req.body;
  if (!body) throw new Error("Hiányzó request body.");

  const bb = Busboy({ headers, limits: { files: 1, fileSize: env.MAX_UPLOAD_BYTES } });

  let filePath: string | null = null;
  let originalFilename: string | null = null;
  let fileWritePromise: Promise<void> | null = null;
  let gotFile = false;

  bb.on("file", (name, file, info) => {
    if (name !== "file") {
      file.resume();
      return;
    }
    if (gotFile) {
      file.resume();
      return;
    }
    gotFile = true;

    originalFilename = info.filename || "video";
    const ext = path.extname(originalFilename).slice(0, 16) || ".bin";
    filePath = path.join(jobDir, `input${ext}`);

    const out = createWriteStream(filePath);
    fileWritePromise = new Promise<void>((resolve, reject) => {
      out.on("finish", () => resolve());
      out.on("error", (e) => reject(e));
      file.on("error", (e) => reject(e));
    });

    file.pipe(out);
  });

  const finishPromise = new Promise<void>((resolve, reject) => {
    bb.on("finish", () => resolve());
    bb.on("error", (e) => reject(e));
  });

  Readable.fromWeb(body as unknown as ReadableStream).pipe(bb);
  await finishPromise;

  if (!filePath || !originalFilename) throw new Error("Nem található feltöltött fájl (file mező).");
  if (fileWritePromise) await fileWritePromise;

  return { filePath, originalFilename };
