import path from "node:path";
import { readdir } from "node:fs/promises";
import { getEnv } from "@/lib/env";
import { rmDir, safeStat } from "@/lib/fs";

export function startCleanupLoop(jobsDir: string) {
  const env = getEnv();
  const ttlMs = env.JOB_TTL_HOURS * 60 * 60 * 1000;

  const run = async () => {
    const now = Date.now();
    let entries: string[] = [];
    try {
      entries = await readdir(jobsDir);
    } catch {
      return;
    }

    await Promise.all(
      entries.map(async (id) => {
        const dir = path.join(jobsDir, id);
        const st = await safeStat(dir);
        if (!st?.isDirectory()) return;
        const age = now - st.mtimeMs;
        if (age > ttlMs) await rmDir(dir);
      })
    );
  };

  run().catch(() => {});
  setInterval(() => {
    run().catch(() => {});
  }, 15 * 60 * 1000);
}
