```ts
import path from "node:path";
import { readFile, writeFile } from "node:fs/promises";
import { v4 as uuidv4 } from "uuid";
import { z } from "zod";
import { ensureDir, rmDir, safeStat } from "@/lib/fs";
import { getEnv } from "@/lib/env";
import { logger } from "@/lib/logger";
import { probeDurationSeconds } from "@/lib/processors/ffprobe";
import { downloadYouTubeToMp4 } from "@/lib/processors/ytdlp";
import { splitIntoSegmentsMp4 } from "@/lib/processors/ffmpeg";
import { zipDirectoryFlat, zipPathForJob } from "@/lib/zip";
import { startCleanupLoop } from "@/lib/cleanup";

const JobStatusSchema = z.enum(["queued", "processing", "completed", "failed"]);
type JobStatus = z.infer<typeof JobStatusSchema>;

const JobRecordSchema = z.object({
  id: z.string().min(1),
  createdAt: z.string().min(1),
  updatedAt: z.string().min(1),
  status: JobStatusSchema,
  inputType: z.enum(["upload", "youtube"]),
  originalName: z.string().optional(),
  youtubeUrl: z.string().optional(),
  inputPath: z.string().optional(),
  durationSeconds: z.number().optional(),
  segmentSeconds: z.number().int().positive(),
  segmentCount: z.number().int().optional(),
  zipPath: z.string().optional(),
  zipBytes: z.number().int().optional(),
  error: z.string().optional()
});
export type JobRecord = z.infer<typeof JobRecordSchema>;

export type JobPaths = {
  jobDir: string;
  jobJsonPath: string;
  segmentsDir: string;
  zipPath: string;
};

const inFlight = new Map<string, Promise<void>>();

function nowIso() {
  return new Date().toISOString();
}

function jobJsonPath(jobDir: string) {
  return path.join(jobDir, "job.json");
}

export function getJobPaths(jobId: string): JobPaths {
  const env = getEnv();
  const jobDir = path.join(env.JOBS_DIR, jobId);
  return {
    jobDir,
    jobJsonPath: jobJsonPath(jobDir),
    segmentsDir: path.join(jobDir, "segments"),
    zipPath: zipPathForJob(jobDir)
  };
}

async function writeJobRecord(job: JobRecord) {
  const paths = getJobPaths(job.id);
  const s = JSON.stringify(job, null, 2);
  await writeFile(paths.jobJsonPath, s, "utf8");
}

async function readJobRecord(jobId: string) {
  const paths = getJobPaths(jobId);
  const raw = await readFile(paths.jobJsonPath, "utf8");
  return JobRecordSchema.parse(JSON.parse(raw));
}

export async function getJobRecord(jobId: string): Promise<JobRecord | null> {
  const paths = getJobPaths(jobId);
  const st = await safeStat(paths.jobJsonPath);
  if (!st?.isFile()) return null;
  return await readJobRecord(jobId);
}

async function createBaseJob(inputType: "upload" | "youtube", extra?: Partial<JobRecord>) {
  const id = uuidv4();
  const paths = getJobPaths(id);
  await ensureDir(paths.jobDir);

  const job: JobRecord = JobRecordSchema.parse({
    id,
    createdAt: nowIso(),
    updatedAt: nowIso(),
    status: "queued",
    inputType,
    segmentSeconds: 60,
    ...extra
  });

  await writeJobRecord(job);
  return { job, paths };
}

export async function createJobFromUpload() {
  const { job, paths } = await createBaseJob("upload");
  return wrapJob(job, paths);
}

export async function createJobFromYouTube(youtubeUrl: string) {
  const { job, paths } = await createBaseJob("youtube", { youtubeUrl });
  return wrapJob(job, paths);
}

function wrapJob(job: JobRecord, paths: JobPaths) {
  return {
    record: job,
    paths,
    attachUploadedFile: async (inputPath: string, originalFilename: string) => {
      const j = await readJobRecord(job.id);
      const upd: JobRecord = {
        ...j,
        updatedAt: nowIso(),
        inputPath,
        originalName: originalFilename
      };
      await writeJobRecord(upd);
      job = upd;
    },
    start: async () => {
      await startJobProcessing(job.id);
    }
  };
}

async function startJobProcessing(jobId: string) {
  if (inFlight.has(jobId)) return;

  const p = (async () => {
    const paths = getJobPaths(jobId);

    let rec = await readJobRecord(jobId);
    if (rec.status === "completed") return;

    rec = { ...rec, status: "processing", updatedAt: nowIso(), error: undefined };
    await writeJobRecord(rec);

    try {
      let inputPath = rec.inputPath;
      if (rec.inputType === "youtube") {
        if (!rec.youtubeUrl) throw new Error("Hiányzó YouTube URL.");
        inputPath = await downloadYouTubeToMp4({ youtubeUrl: rec.youtubeUrl, jobDir: paths.jobDir });
        rec = { ...rec, inputPath, updatedAt: nowIso() };
        await writeJobRecord(rec);
      }

      if (!inputPath) throw new Error("Hiányzó bemeneti fájl.");

      const durationSeconds = await probeDurationSeconds(inputPath);
      rec = { ...rec, durationSeconds, updatedAt: nowIso() };
      await writeJobRecord(rec);

      const split = await splitIntoSegmentsMp4({ inputPath, segmentsDir: paths.segmentsDir, segmentSeconds: rec.segmentSeconds });
      const segmentCount = split.files.length;

      const zipBytes = await zipDirectoryFlat({ sourceDir: paths.segmentsDir, zipPath: paths.zipPath });

      rec = {
        ...rec,
        status: "completed",
        updatedAt: nowIso(),
        segmentCount,
        zipPath: paths.zipPath,
        zipBytes
      };
      await writeJobRecord(rec);
    } catch (e) {
      const msg = e instanceof Error ? e.message : "Ismeretlen hiba.";
      logger.error({ jobId, err: msg }, "job failed");
      const latest = await readJobRecord(jobId);
      const failed: JobRecord = { ...latest, status: "failed", updatedAt: nowIso(), error: msg };
      await writeJobRecord(failed);
    } finally {
      inFlight.delete(jobId);
    }
  })();

  inFlight.set(jobId, p);
  await p;
}

async function resumeQueuedJobs() {
  const env = getEnv();
  await ensureDir(env.JOBS_DIR);
  const { readdir } = await import("node:fs/promises");
  let entries: string[] = [];
  try {
    entries = await readdir(env.JOBS_DIR);
  } catch {
    return;
  }

  await Promise.all(
    entries.map(async (jobId) => {
      const paths = getJobPaths(jobId);
      const st = await safeStat(paths.jobJsonPath);
      if (!st?.isFile()) return;
      let rec: JobRecord;
      try {
        rec = await readJobRecord(jobId);
      } catch {
        await rmDir(paths.jobDir);
        return;
      }
      if (rec.status === "queued" || rec.status === "processing") {
        startJobProcessing(jobId).catch(() => {});
      }
    })
  );
}

declare global {
  var __jobSystemStarted: boolean | undefined;
}

export async function ensureJobSystemStarted() {
  if (globalThis.__jobSystemStarted) return;
  globalThis.__jobSystemStarted = true;

  const env = getEnv();
  await ensureDir(env.JOBS_DIR);
  startCleanupLoop(env.JOBS_DIR);
  await resumeQueuedJobs();
}
